        if tok.kind == _TOK_NAME and tok.value in _CLAUSE_KEYWORDS:
            raise self._error(
                f"{label}内不得嵌套 OPTIONAL 或 FILTER",
                tok.pos,
            )
        if tok.kind == _TOK_LBRACE:
            raise self._error(
                f"{label}内不得嵌套花括号分组",
                tok.pos,
